const { useEffect, useRef, useState } = React;

// 关键字与 superellipse() 参数的对应关系，按从凹到凸排列
const KEYWORDS = [
  { name: "notch", k: -Infinity },
  { name: "scoop", k: -1 },
  { name: "bevel", k: 0 },
  { name: "round", k: 1 },
  { name: "squircle", k: 2 },
  { name: "square", k: Infinity },
];
const K_MIN = -4;
const K_MAX = 6;
const formatK = k => (k === Infinity ? "infinity" : k === -Infinity ? "-infinity" : String(Math.round(k * 10) / 10));

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Slider = ({ label, value, min, max, step = 1, onChange, display }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-16 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{display}</span>
  </label>
);

const Component = () => {
  const shapeRef = useRef(null);
  const [keyword, setKeyword] = useState("scoop");
  const [k, setK] = useState(-1);
  const [radius, setRadius] = useState(48);
  const [compare, setCompare] = useState(true);
  const [supported, setSupported] = useState(true);

  const cornerShape = keyword ?? `superellipse(${formatK(k)})`;

  // corner-shape 不在 React 已知的样式属性里，经 setProperty 写入
  useEffect(() => {
    shapeRef.current.style.setProperty("corner-shape", cornerShape);
  }, [cornerShape]);
  useEffect(() => {
    setSupported(Boolean(window.CSS?.supports?.("corner-shape", "bevel")));
  }, []);

  const pickKeyword = item => {
    setKeyword(item.name);
    setK(Math.min(K_MAX, Math.max(K_MIN, item.k)));
  };
  const slide = value => {
    setKeyword(null);
    setK(value);
  };
  const equivalent = KEYWORDS.find(item => item.name === keyword)?.k ?? k;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
          .cb-shape { transition: border-radius 300ms var(--tau-ease-out); }
        }
      `}</style>
      <div className="flex flex-wrap items-center gap-2">
        {KEYWORDS.map(item => (
          <Choice key={item.name} active={keyword === item.name} onClick={() => pickKeyword(item)}>
            {item.name}
          </Choice>
        ))}
        <Choice active={keyword === null} onClick={() => slide(k)}>
          superellipse()
        </Choice>
      </div>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative grid min-h-[260px] place-items-center rounded-tau-md border border-line-1 p-6">
          <div className="relative size-44">
            <div
              ref={shapeRef}
              className="cb-shape absolute inset-0 border-2 border-accent bg-accent-soft shadow-lift"
              style={{ borderRadius: radius }}
            />
            {compare && (
              <div
                className="pointer-events-none absolute inset-0 border border-dashed border-ink-3"
                style={{ borderRadius: radius }}
              />
            )}
          </div>
          {!supported && (
            <span className="absolute left-3 top-3 rounded-full bg-warn-soft px-2.5 py-0.5 text-tau-sm text-warn">
              当前浏览器不支持 corner-shape
            </span>
          )}
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <pre className="m-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
            <div>border-radius: {radius}px;</div>
            <div>
              corner-shape: <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{cornerShape}</span>;
            </div>
          </pre>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            <dt className="text-ink-3">等价写法</dt>
            <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">superellipse({formatK(equivalent)})</dd>
            <dt className="text-ink-3">形状</dt>
            <dd className="m-0 text-ink-1">
              {equivalent < 0 ? "向内凹" : equivalent === 0 ? "直线斜切" : equivalent === 1 ? "普通圆角" : equivalent < 1 ? "介于斜切与圆角" : "更饱满，趋近方角"}
            </dd>
          </dl>
          {radius === 0 && (
            <p className="m-0 rounded-tau-md bg-warn-soft px-3 py-2 text-tau-sm text-warn">
              border-radius 为 0，角没有范围，corner-shape 不起作用。
            </p>
          )}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <Slider label={`border-radius`} value={radius} min={0} max={88} onChange={setRadius} display={`${radius}px`} />
        <Slider label="superellipse" value={k} min={K_MIN} max={K_MAX} step={0.1} onChange={slide} display={formatK(equivalent)} />
        <ui.Switch checked={compare} onCheckedChange={setCompare} label="叠加 round 轮廓" />
      </div>
    </div>
  );
};

