const { useEffect, useRef, useState } = React;

const DURATION_MS = 4000;
// 关键帧：每个关键字在动画进度中的位置；插值时浏览器按 superellipse() 参数过渡
const STOPS = [
  { at: 0, name: "scoop" },
  { at: 0.25, name: "bevel" },
  { at: 0.5, name: "notch" },
  { at: 0.75, name: "squircle" },
  { at: 1, name: "round" },
];

const STYLE = `
  @scope {
    .cb-morph {
      border-radius: 40px;
      animation: cb-corner-morph ${DURATION_MS}ms ease-in-out infinite alternate;
    }
    .cb-morph[data-spin="on"] {
      animation:
        cb-corner-morph ${DURATION_MS}ms ease-in-out infinite alternate,
        cb-corner-spin ${DURATION_MS}ms ease-in-out infinite alternate;
    }
    .cb-morph[data-playing="off"] { animation-play-state: paused; }
  }
  @keyframes cb-corner-morph {
    0% { corner-shape: scoop; }
    25% { corner-shape: bevel; }
    50% { corner-shape: notch; }
    75% { corner-shape: squircle; }
    100% { corner-shape: round; }
  }
  @keyframes cb-corner-spin {
    0% { transform: rotate(0deg); }
    25% { transform: rotate(90deg); }
    50% { transform: rotate(180deg); }
    75% { transform: rotate(270deg); }
    100% { transform: rotate(360deg); }
  }
`;

const nearestStop = progress =>
  STOPS.reduce((best, stop) => (Math.abs(stop.at - progress) < Math.abs(best.at - progress) ? stop : best));

const Component = () => {
  const shapeRef = useRef(null);
  const [playing, setPlaying] = useState(true);
  const [spin, setSpin] = useState(true);
  const [progress, setProgress] = useState(0);
  const [forward, setForward] = useState(true);
  const [computed, setComputed] = useState("");

  // 逐帧读取动画进度与插值中的 corner-shape 计算值
  useEffect(() => {
    let frame = 0;
    const tick = () => {
      const shape = shapeRef.current;
      const morph = shape.getAnimations?.().find(animation => animation.animationName === "cb-corner-morph");
      const timing = morph?.effect?.getComputedTiming();
      if (timing && timing.progress !== null) {
        setProgress(timing.progress);
        setForward(timing.currentIteration % 2 === 0);
      }
      setComputed(getComputedStyle(shape).getPropertyValue("corner-shape"));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, []);

  // 定格到某个关键帧：暂停后把所有动画拨到同一时刻
  const seek = stop => {
    setPlaying(false);
    for (const animation of shapeRef.current.getAnimations?.() ?? []) {
      animation.currentTime = stop.at * DURATION_MS;
    }
  };

  const active = nearestStop(progress);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="grid min-h-[260px] place-items-center rounded-tau-md border border-line-1 p-6">
          <div
            ref={shapeRef}
            data-spin={spin ? "on" : "off"}
            data-playing={playing ? "on" : "off"}
            className="cb-morph size-40 border-2 border-accent bg-accent-soft shadow-lift"
          />
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <pre className="m-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
            <div className="text-accent-text">@keyframes morphShape {"{"}</div>
            {STOPS.map(stop => (
              <div
                key={stop.name}
                className={`rounded-tau-sm px-1 transition-colors ${active === stop ? "bg-accent-soft text-accent-text" : ""}`}
              >
                {"  "}
                {stop.at * 100}% {"{"} corner-shape: {stop.name}; {"}"}
              </div>
            ))}
            <div className="text-accent-text">{"}"}</div>
          </pre>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            <dt className="text-ink-3">进度</dt>
            <dd className="m-0 font-tau-mono text-ink-1">
              {Math.round(progress * 100)}%{forward ? "" : "（反向）"}
            </dd>
            <dt className="text-ink-3">计算值</dt>
            <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">{computed || "—"}</dd>
          </dl>
        </div>
      </div>
      <div className="relative mx-8 h-10">
        <div className="absolute inset-x-0 top-1.5 h-1 rounded-full bg-track" />
        <div className="absolute left-0 top-1.5 h-1 rounded-full bg-accent" style={{ width: `${progress * 100}%` }} />
        {STOPS.map(stop => (
          <button
            key={stop.name}
            type="button"
            onClick={() => seek(stop)}
            className="absolute top-0 flex -translate-x-1/2 cursor-pointer flex-col items-center gap-1"
            style={{ left: `${stop.at * 100}%` }}
          >
            <span
              className={`size-3 rounded-full border-2 transition-colors ${
                active === stop ? "border-accent bg-accent" : "border-line-1 bg-surface"
              }`}
              style={{ marginTop: 2 }}
            />
            <span className={`font-tau-mono text-tau-tiny ${active === stop ? "text-accent-text" : "text-ink-3"}`}>{stop.name}</span>
          </button>
        ))}
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button
          variant="secondary"
          size="sm"
          icon={playing ? icons.Pause : icons.Play}
          onClick={() => setPlaying(value => !value)}
        >
          {playing ? "暂停" : "播放"}
        </ui.Button>
        <ui.Switch checked={spin} onCheckedChange={setSpin} label="同时旋转" />
        <span className="text-tau-sm text-ink-3">点击时间轴上的关键字可定格查看</span>
      </div>
    </div>
  );
};
